contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address target) public payable {
        require(target != address(0));

        bool reverted;
        bool success;
        bool s = c.setOwner(target); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            success = false;
        } else {
            success = s;
            reverted = false;
        }

        assert(reverted || success == true);
    }
}

